    """Raised when the stack does not hold enough items for an operation."""

    def __init__(self, message):
        super().__init__(message)
        self.message = message


def _is_number(token):
    return token.isascii() and token.isdigit()


def _div(a, b):
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    return a // b


BINARY = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "/": _div,
}


def _need(stack, n):
    if len(stack) < n:
        raise StackUnderflowError("Insufficient number of items in stack")


def _run(tokens, stack, words):
    for tok in tokens:
        if _is_number(tok):
            stack.append(int(tok))
        elif tok in BINARY:
            _need(stack, 2)
            b = stack.pop()
            a = stack.pop()
            stack.append(BINARY[tok](a, b))
        elif tok == "dup":
            _need(stack, 1)
            stack.append(stack[-1])
        elif tok == "drop":
            _need(stack, 1)
            stack.pop()
        elif tok == "swap":
            _need(stack, 2)
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif tok == "over":
            _need(stack, 2)
            stack.append(stack[-2])
        else:
            raise ValueError("undefined operation")


def evaluate(input_data):
    stack = []
    words = {}
    for line in input_data:
        tokens = line.lower().split()
        out = []
        i = 0
        while i < len(tokens):
            tok = tokens[i]
            if tok == ":":
                try:
                    end = tokens.index(";", i)
                except ValueError:
                    raise ValueError("undefined operation")
                if end - i < 2:
                    raise ValueError("illegal operation")
                name = tokens[i + 1]
                if _is_number(name):
                    raise ValueError("illegal operation")
                body = []
                for t in tokens[i + 2:end]:
                    body.extend(words.get(t, [t]))
                words[name] = body
                i = end + 1
                continue
            out.extend(words.get(tok, [tok]))
            i += 1
        _run(out, stack, words)
    return stack
